mapper.select:
SELECT , (SELECT COUNT(*) FROM trip_stop s WHERE s.trip_id = t.trip_id AND s.state <> 'skipped') AS stop_count
FROM trip t WHERE t.member_id = #{memberId}
ORDER BY t.start_date DESC, t.trip_id DESC

mapper.update:
UPDATE trip SET title = #{title}, start_date = #{startDate}::date, end_date = #{endDate}::date, people = #{people},
       transports = #{transports, typeHandler=com.tripbiseo.config.CsvTypeHandler}, updated_at = NOW()
WHERE trip_id = #{id} AND member_id = #{memberId}
